package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/smtp"
	"os"
	"strings"
	"sync"
	"time"
)

const (
	smtpHost     = "mail.internal:587"
	notifyFrom   = "chat-notify@example.com"
	maxMsgLen    = 500
	rateLimit    = 5
	rateDuration = time.Minute
)

// hmacSecret is loaded from the environment to avoid hardcoding secrets in source.
var hmacSecret = func() string {
	s := os.Getenv("HMAC_SECRET")
	if s == "" {
		panic("HMAC_SECRET environment variable must be set")
	}
	return s
}()

type RateLimiter struct {
	mu       sync.Mutex
	counters map[string][]time.Time
}

func NewRateLimiter() *RateLimiter {
	return &RateLimiter{counters: make(map[string][]time.Time)}
}

func (rl *RateLimiter) Allow(key string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	now := time.Now()
	window := now.Add(-rateDuration)
	var valid []time.Time
	for _, t := range rl.counters[key] {
		if t.After(window) {
			valid = append(valid, t)
		}
	}
	if len(valid) >= rateLimit {
		return false
	}
	rl.counters[key] = append(valid, now)
	return true
}

type ChatServer struct {
	limiter *RateLimiter
}

func NewChatServer() *ChatServer {
	return &ChatServer{limiter: NewRateLimiter()}
}

func (cs *ChatServer) verifyServiceToken(token string, payload string) bool {
	mac := hmac.New(sha256.New, []byte(hmacSecret))
	mac.Write([]byte(payload))
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(token))
}

func sanitizeDisplayName(name string) string {
	name = strings.Map(func(r rune) rune {
		if r == '<' || r == '>' || r == '"' || r == '\'' {
			return -1
		}
		return r
	}, name)
	if len(name) > 64 {
		name = name[:64]
	}
	return name
}

func sanitizeForHeader(value string) string {
	// Remove characters that could enable header injection
	result := strings.ReplaceAll(value, "\r", "")
	result = strings.ReplaceAll(result, "\n", "")
	return result
}

func buildNotificationEmail(to, displayName, roomName, msgPreview string) string {
	safeName := sanitizeDisplayName(displayName)
	safeRoom := sanitizeForHeader(roomName)
	// Subject is built from room name - sanitized above
	subject := fmt.Sprintf("New message in %s", safeRoom)
	// Build RFC 2822 message
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("From: %s\r\n", notifyFrom))
	sb.WriteString(fmt.Sprintf("To: %s\r\n", sanitizeForHeader(to)))
	sb.WriteString(fmt.Sprintf("Subject: %s\r\n", subject))
	sb.WriteString(fmt.Sprintf("X-Chat-User: %s\r\n", sanitizeForHeader(safeName)))
	sb.WriteString("MIME-Version: 1.0\r\n")
	sb.WriteString("Content-Type: text/plain; charset=UTF-8\r\n")
	sb.WriteString("\r\n")
	sb.WriteString(fmt.Sprintf("%s wrote in %s:\r\n\r\n%s", safeName, safeRoom, msgPreview))
	return sb.String()
}

func (cs *ChatServer) handleNotify(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	serviceToken := r.Header.Get("X-Service-Auth")
	if serviceToken == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	userEmail := r.FormValue("email")
	displayName := r.FormValue("display_name")
	roomName := r.FormValue("room")
	message := r.FormValue("message")

	// Verify HMAC over the full payload including message
	canonical := fmt.Sprintf("%s|%s|%s|%s", userEmail, displayName, roomName, message)
	if !cs.verifyServiceToken(serviceToken, canonical) {
		http.Error(w, "invalid token", http.StatusForbidden)
		return
	}

	if !cs.limiter.Allow(userEmail) {
		http.Error(w, "rate limited", http.StatusTooManyRequests)
		return
	}

	if len(message) > maxMsgLen {
		message = message[:maxMsgLen]
	}

	// Sanitize message for safe inclusion
	message = sanitizeForHeader(message)

	emailContent := buildNotificationEmail(userEmail, displayName, roomName, message)

	err := smtp.SendMail(smtpHost, nil, notifyFrom, []string{sanitizeForHeader(userEmail)}, []byte(emailContent))
	if err != nil {
		http.Error(w, "notification failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte("notification sent"))
}

func main() {
	server := NewChatServer()
	http.HandleFunc("/internal/notify", server.handleNotify)
	fmt.Println("Chat notification service on :8443")
	http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil)
}
